mapper.select:
SELECT P.MERCHANT_ID, P.BASE_DATE, P.TX_SEQ, P.MERCHANT_ORDER_ID, P.MERCHANT_ORDER_DATE, P.PAY_METHOD, (SELECT CODE_NAME FROM MST_CODE WHERE CODE = P.PAY_METHOD) AS PAY_METHOD_NAME, P.AMOUNT, P.PAY_STATUS, (SELECT CODE_NAME FROM MST_CODE WHERE CODE = P.PAY_STATUS) AS PAY_STATUS_NAME, P.CREATED_AT FROM PAYMENT P WHERE 1=1
AND P.MERCHANT_ID = #{dto.merchantId}
AND P.BASE_DATE >= #{dto.baseDateFrom}
AND P.BASE_DATE <= #{dto.baseDateTo}
AND P.PAY_METHOD = #{dto.payMethod}
AND P.PAY_STATUS = #{dto.payStatus}
ORDER BY P.MERCHANT_ID, P.BASE_DATE, P.TX_SEQ OFFSET #{dto.offset} ROWS FETCH NEXT #{dto.size} ROWS ONLY

SELECT COUNT(*) CNT
FROM PAYMENT P
WHERE 1=1


    AND P.MERCHANT_ID = #{dto.merchantId}



    AND P.BASE_DATE >= #{dto.baseDateFrom}



    AND P.BASE_DATE <= #{dto.baseDateTo}



    AND P.PAY_METHOD = #{dto.payMethod}



    AND P.PAY_STATUS = #{dto.payStatus}
